import * as crypto from "node:crypto";
function main(): void {
  crypto.pbkdf2("pw", "salt", 10, 8, "sha1", (e, k) => {
    console.log("pbkdf2", e, k.toString("hex"));
    crypto.randomBytes(4, (e2, b) => {
      console.log("randomBytes", e2, b.length);
      crypto.scrypt("pw", "salt", 8, (e3, k3) => {
        console.log("scrypt", e3, k3.toString("hex"));
        crypto.hkdf("sha256", "key", "salt", "info", 8, (e4, k4) => console.log("hkdf", e4, k4.byteLength));
      });
    });
  });
}
